import { Workshop, WorkshopFilter, WorkshopRow, WorkshopToolbar } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function jsonEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

async function main(): Promise<void> {
  const reports: unknown[] = [];
  const toolbar = new WorkshopToolbar(async () => [], workshop => ({ key: String(workshop.id), label: workshop.title, room: workshop.roomCode }), async () => false, error => reports.push(error));
  const order: string[] = [];
  let firstReceived: WorkshopFilter | null = null;
  let secondReceived: WorkshopFilter | null = null;
  const unsubscribeFirst = toolbar.subscribe(filter => {
    order.push('first');
    firstReceived = filter;
    filter.text = 'mutated';
    filter.room = 'changed';
  });
  toolbar.subscribe(filter => {
    order.push('second');
    secondReceived = filter;
  });
  const callerFilter: WorkshopFilter = { text: 'query', room: 'A' };
  toolbar.emitFilter(callerFilter);
  jsonEqual(order, ['first', 'second'], 'listeners run synchronously in order');
  jsonEqual(callerFilter, { text: 'query', room: 'A' }, 'caller filter is not mutated');
  jsonEqual(secondReceived, { text: 'query', room: 'A' }, 'listener mutation is isolated');
  assert(firstReceived !== secondReceived && firstReceived !== callerFilter && secondReceived !== callerFilter, 'every listener receives a distinct copy');
  unsubscribeFirst();
  unsubscribeFirst();
  toolbar.emitFilter({ text: 'again', room: null });
  jsonEqual(order, ['first', 'second', 'second'], 'unsubscribe is idempotent');

  const source: Workshop[] = [
    { id: 2, title: 'Second', roomCode: 'R2' },
    { id: 1, title: 'First', roomCode: 'R1' },
  ];
  const mappedObjects: WorkshopRow[] = [];
  const loaded = new WorkshopToolbar(async () => source, workshop => {
    const row = { key: String(workshop.id), label: workshop.title, room: workshop.roomCode };
    mappedObjects.push(row);
    return row;
  }, async () => false, error => reports.push(error));
  assert(await loaded.initialize(), 'successful initialization returns true');
  jsonEqual(loaded.getRows(), [
    { key: '2', label: 'Second', room: 'R2' },
    { key: '1', label: 'First', room: 'R1' },
  ], 'rows preserve source order');
  mappedObjects[0].label = 'changed externally';
  source[0].title = 'changed source';
  const rowsOne = loaded.getRows();
  assert(rowsOne[0].label === 'Second', 'stored rows do not alias mapper or source data');
  rowsOne[0].label = 'changed return';
  const rowsTwo = loaded.getRows();
  assert(rowsTwo[0].label === 'Second' && rowsOne !== rowsTwo && rowsOne[0] !== rowsTwo[0], 'getRows returns object and array copies');

  let failMapping = false;
  const mappingError = new Error('mapping');
  const transactionalReports: unknown[] = [];
  const transactional = new WorkshopToolbar(async () => source, workshop => {
    if (failMapping && workshop.id === 1) throw mappingError;
    return { key: String(workshop.id), label: workshop.title, room: workshop.roomCode };
  }, async () => false, error => transactionalReports.push(error));
  assert(await transactional.initialize(), 'transactional baseline initializes');
  const baseline = transactional.getRows();
  failMapping = true;
  assert(!(await transactional.initialize()), 'mapping failure returns false');
  jsonEqual(transactional.getRows(), baseline, 'mapping failure preserves previous rows');
  assert(transactionalReports.length === 1 && transactionalReports[0] === mappingError, 'mapping failure reported exactly once');

  const loadError = new Error('load');
  const loadReports: unknown[] = [];
  const loadFailure = new WorkshopToolbar(async () => { throw loadError; }, workshop => ({ key: String(workshop.id), label: workshop.title, room: workshop.roomCode }), async () => false, error => loadReports.push(error));
  assert(!(await loadFailure.initialize()), 'loading failure returns false');
  assert(loadReports.length === 1 && loadReports[0] === loadError, 'loading failure reported exactly once');

  let loads = 0;
  const emitted: WorkshopFilter[] = [];
  const added = new WorkshopToolbar(async () => {
    loads += 1;
    return [{ id: 9, title: 'New', roomCode: 'N' }];
  }, workshop => ({ key: String(workshop.id), label: workshop.title, room: workshop.roomCode }), async () => true, error => reports.push(error));
  added.subscribe(filter => emitted.push(filter));
  assert(await added.openAddDialog(), 'confirmed dialog with successful reload returns true');
  assert(loads === 1, 'confirmed dialog initializes once');
  jsonEqual(emitted, [{ text: '', room: null }], 'successful addition emits reset filter');

  let cancelledLoads = 0;
  const cancelled = new WorkshopToolbar(async () => { cancelledLoads += 1; return []; }, workshop => ({ key: String(workshop.id), label: workshop.title, room: workshop.roomCode }), async () => false, error => reports.push(error));
  assert(!(await cancelled.openAddDialog()) && cancelledLoads === 0, 'cancelled dialog does nothing');

  const dialogError = new Error('dialog');
  const dialogReports: unknown[] = [];
  const dialogFailure = new WorkshopToolbar(async () => [], workshop => ({ key: String(workshop.id), label: workshop.title, room: workshop.roomCode }), async () => { throw dialogError; }, error => dialogReports.push(error));
  assert(!(await dialogFailure.openAddDialog()), 'dialog rejection returns false');
  assert(dialogReports.length === 1 && dialogReports[0] === dialogError, 'dialog rejection reported exactly once');

  const failedEmissions: WorkshopFilter[] = [];
  const initError = new Error('reload');
  const failedReports: unknown[] = [];
  const failedAdd = new WorkshopToolbar(async () => { throw initError; }, workshop => ({ key: String(workshop.id), label: workshop.title, room: workshop.roomCode }), async () => true, error => failedReports.push(error));
  failedAdd.subscribe(filter => failedEmissions.push(filter));
  assert(!(await failedAdd.openAddDialog()), 'failed initialization after confirmation returns false');
  assert(failedEmissions.length === 0, 'failed initialization does not emit');
  assert(failedReports.length === 1 && failedReports[0] === initError, 'failed reload reports exactly once');
}

main().catch((error: unknown) => { throw error; });

